import { readFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import path from "node:path";
import { emitModels, writeGenerated } from "./lib/contract-codegen.mjs";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const contract = JSON.parse(
  await readFile(path.join(root, "contracts/workforce-person-reviews.json"), "utf8"),
);
const models = emitModels(contract.models);
await writeGenerated(
  root,
  "backend/internal/modules/workforce/person_review_types.go",
  '// Code generated by scripts/generate-workforce-person-reviews.mjs; DO NOT EDIT.\npackage workforce\nimport("time";"github.com/google/uuid")\n' +
    models.go,
  "packages/api/src/person-review-contract.ts",
  '// Generated by scripts/generate-workforce-person-reviews.mjs.\nimport {z} from "zod";\n' +
    models.ts,
  "Staff person review",
);
